// Author: MiYu. Focused JASS type diagnostics and resolved runtime slot boundaries.
#include "jass_module.h"
#include <functional>
#include <iostream>

using namespace war3;
using namespace war3::jass;
namespace {
void require(bool value,const char* message) {if(!value)throw std::runtime_error(message);}
Module compile(std::string text) {return Module::compile(Program::parse({{"fixture.j",std::move(text),"authored test"}}));}
void rejects(const std::string& text,const char* message) {try{compile(text);}catch(const std::runtime_error& e){auto diagnostic=std::string(e.what());require(diagnostic.starts_with("fixture.j:"),"Diagnostic lacks source position");require(diagnostic.find(message)!=std::string::npos,"Unexpected type diagnostic");return;}throw std::runtime_error("Invalid typed JASS accepted");}
std::string function(const std::string& body,const char* result="nothing") {return std::string("function f takes nothing returns ")+result+"\n"+body+"\nendfunction\n";}
}
int main() {
    unsigned passed=0,failed=0;auto test=[&](const char* name,const std::function<void()>& run){try{run();++passed;std::cout<<"PASS "<<name<<'\n';}catch(const std::exception& e){++failed;std::cout<<"FAIL "<<name<<": "<<e.what()<<'\n';}};
    test("module_handle_ancestry_and_null",[]{auto m=compile("type agent extends handle\ntype unit extends agent\ntype timer extends handle\n");auto u=m.typeId("unit"),a=m.typeId("agent"),h=m.typeId("handle"),n=m.typeId("<null>");require(m.assignable(h,u) && m.assignable(a,u) && !m.assignable(u,a) && !m.assignable(m.typeId("timer"),u),"Handle ancestry differs");for(auto name:{"handle","unit","code","string"})require(m.assignable(m.typeId(name),n),"Nullable type rejected null");for(auto name:{"integer","real","boolean","nothing"})require(!m.assignable(m.typeId(name),n),"Null accepted as scalar");require(m.assignable(m.typeId("real"),m.typeId("integer")) && !m.assignable(m.typeId("integer"),m.typeId("real")),"Numeric widening differs");});
    test("module_invalid_type_graph",[]{rejects("type unit extends missing\n","must extend a handle");rejects("type unit extends integer\n","must extend a handle");rejects("type a extends b\ntype b extends a\n","Cyclic");rejects("type a extends a\n","Cyclic");rejects("type integer extends handle\n","Duplicate builtin");rejects("globals\nnothing x\nendglobals\n","Invalid JASS value type");rejects(function("local missing x"),"Unknown JASS type");});
    test("module_parameter_local_global_slots",[]{auto m=compile("globals\ninteger x\ninteger y\nendglobals\nfunction f takes integer x returns integer\nlocal integer y=x\nlocal integer array values\nset values[x]=y\nset y=values[x]\nreturn y\nendfunction\nfunction g takes nothing returns integer\nset x=y\nreturn x\nendfunction\n");auto& p=m.program();auto f=p.function("f"),g=p.function("g");auto& signature=m.functions()[m.functionId("f")];require(signature.parameters.size()==1 && signature.slots.size()==3 && signature.slots[2].array,"Local slots differ");auto initializer=m.binding(f->locals[0].initializer);require(initializer.access==Access::Local && initializer.index==0,"Parameter shadowing differs");auto first=m.assignment(f->body[0]),second=m.assignment(f->body[1]),global=m.assignment(g->body[0]);require(first.access==Access::Local && first.index==2 && second.index==1 && global.access==Access::Global && global.index==0,"Assignment slot binding differs");auto read=m.binding(p.statement(g->body[0]).value);require(read.access==Access::Global && read.index==1,"Global binding differs");require(m.binding(p.statement(f->body.back()).value).index==1,"Local return binding differs");});
    test("module_calls_forward_references_and_code",[]{auto m=compile("type unit extends handle\nnative consume takes handle h, real r, code callback returns nothing\nglobals\nunit u=null\nendglobals\nfunction f takes nothing returns nothing\ncall consume(u,2,function later)\ncall later()\nendfunction\nfunction later takes nothing returns nothing\nendfunction\n");auto& p=m.program();auto& call=p.expression(p.statement(p.function("f")->body[0]).value);auto b=m.binding(call.operands[2]);require(b.access==Access::Function && b.index==m.functionId("later") && b.type==m.typeId("code"),"Code reference unresolved");require(m.binding(p.statement(p.function("f")->body[1]).value).index==m.functionId("later"),"Forward call unresolved");rejects("native consume takes real r returns nothing\n"+function("call consume()"),"argument count");rejects("native consume takes real r returns nothing\n"+function("call consume(true)"),"Argument 1 of consume");rejects(function("call unknown()"),"Unknown JASS function");rejects(function("return function unknown","code"),"Unknown JASS function");});
    test("module_array_shape_and_index",[]{auto prefix=std::string("globals\ninteger array a\ninteger x\nendglobals\n");compile(prefix+function("set a[0]=x\nset x=a[1]"));for(auto body:{"set a=1","set x[0]=1"})rejects(prefix+function(body),"shape differs");rejects(prefix+function("set x=a"),"requires index");rejects(prefix+function("set x=x[0]"),"Scalar JASS variable indexed");rejects(prefix+function("set a[1.0]=2"),"Array index");rejects(prefix+function("set x=a[false]"),"Array index");});
    test("module_initializer_and_constant_checks",[]{compile("globals\nconstant real r=2\nendglobals\n"+function("local real x=r\nset x=1"));rejects("globals\nconstant integer c=1\nendglobals\n"+function("set c=2"),"constant");rejects("globals\nconstant integer array a\nendglobals\n","Constant JASS array");rejects("globals\ninteger x=1.0\nendglobals\n","Global x");rejects(function("local boolean x=1"),"Local x");rejects(function("local integer x=y\nlocal integer y=1"),"Unknown JASS variable");});
    test("module_flow_return_and_operators",[]{compile(function("if not false and 1<2.0 then\nloop\nexitwhen true\nendloop\nendif\nreturn"));compile(function("return 1+2.0*3","real"));compile(function("return null+\"text\"","string"));compile(function("return null==\"text\"","boolean"));rejects(function("if 1 then\nendif"),"if expects boolean");rejects(function("loop\nexitwhen 1\nendloop"),"exitwhen expects boolean");rejects(function("return 1"),"Void JASS function");rejects(function("return","integer"),"return value missing");rejects(function("return 1.0","integer"),"Return expects integer");rejects(function("return true+1","integer"),"requires numbers");rejects(function("return not 1","boolean"),"not expects boolean");rejects(function("return -true","boolean"),"arithmetic requires number");rejects(function("return 1==null","boolean"),"Incompatible JASS equality");rejects(function("return true and 1","boolean"),"and expects boolean");});
    test("module_long_expression_uses_bounded_host_stack",[]{std::string expression="1";for(unsigned i=0;i<20000;++i)expression+="+1";auto m=compile(function("return "+expression,"integer"));auto result=m.program().statement(m.program().function("f")->body[0]).value;require(m.binding(result).type==m.typeId("integer"),"Long expression binding differs");});
    test("module_binding_coverage_and_ownership",[]{auto m=compile("globals\ninteger array a\nendglobals\nfunction f takes integer i returns real\nlocal real x=2\nif i>0 then\nset a[i]=i+1\nelse\ncall f(a[i])\nendif\nreturn x\nendfunction\n");auto moved=std::move(m);require(moved.program().sources()[0].text.find("function f")!=std::string::npos,"Module lost owned source");for(size_t i=0;i<moved.program().expressionCount();++i)require(moved.binding(Id(i)).type!=none,"Expression left unbound");require(moved.functionId("missing")==none && moved.typeId("missing")==none,"Unknown symbol lookup differs");});
    require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded into module checks");std::cout<<"RESULT passed="<<passed<<" failed="<<failed<<'\n';return failed?1:0;
}
